  async function prepareCustomOrderDesign(raw){
    const design=clone(raw||{});
    const [front,back]=await Promise.all([renderCustomOrderSide(design,'front'),renderCustomOrderSide(design,'back')]);
    if(front)design.frontCompositeDataUrl=front;if(back)design.backCompositeDataUrl=back;return design;
  }
  async function completeOrder(){
    if(state.orderSubmitting||!state.cart.length)return;
    const orderCart=clone(state.cart),orderTotal=subtotal();
    state.orderSubmitting=true;state.authBusy=true;state.payment='Cash on delivery';render();
    try{
      const prepared=[];for(const item of orderCart){if(item.itemType==='custom_design')prepared.push({...item,preparedDesign:await prepareCustomOrderDesign(item.design||item.customDesign||{})});else prepared.push(item);}
      const payload={customerName:state.details.name||state.customer?.name||'',phone:state.customer?.phone||state.details.phone||'',address:state.details.address||'',business:state.details.business||'',delivery:state.delivery,payment:'Cash on delivery',items:prepared.map(item=>item.itemType==='custom_design'?{itemType:item.itemType,key:item.key||'',name:item.name,code:item.code||'CUSTOM',qty:item.qty||1,unitPrice:Number(item.price||0),design:item.preparedDesign||item.design||item.customDesign||{}}:{itemType:'product',productId:item.productId,name:item.name,code:item.code||'',lines:item.bulkLines||[]})};
      await cartMutationQueue;
      if(cartSyncError)throw new Error('Cart is not fully synced yet. '+cartSyncError);
      B?.customerEvent?.('order_submit_attempt',{delivery:state.delivery,payment:state.payment,items:orderCart.map(i=>({name:i.name,code:i.code||'',itemType:i.itemType||'product',qty:i.qty||1}))});
      const r=await B.placeOrder(payload);
      state.orderReference=r.orderCode||r.id||'ORDER';state.orderPlaced=false;state.paymentDemo=false;state.cart=[];state.cartVersion=Number(state.cartVersion||0)+1;broadcastAccountSync('order');
      await B.hydrate();await refreshCustomerAccount(false);
      state.orderSubmitting=false;state.authBusy=false;state.checkoutStep=1;
      go('orders');
    }catch(e){
      state.orderSubmitting=false;state.authBusy=false;showToast(e.message||'Could not place order');
    }
  }
  function whatsAppUrl(message){const text=encodeURIComponent(message||'Hi, I need a customization quotation.');return 'https://wa.me/'+WHATSAPP_NUMBER+'?text='+text;}
  function openWhatsApp(message){window.open(whatsAppUrl(message),'_blank','noopener');}
